@startuml

class Product {
  + name : string
  + description : string
  + netPrice : double
}

class Manufacturer {
  + name : string
}

class Country {
  + name : string
  + vatRate : double
  + currency : string
  + conversionRateToEuro : double
}

class Representative {
  + firstName : string
  + lastName : string
  + socialSecurityNumber : string
  + telephone : string
  + email : string
}

class Customer {
  + name : string
  + address : string
  + telephone : string
  + email : string
}

class Order {
  + orderId : string
  + quantity : int
  + orderDate : date
  + desiredDeliveryDate : date
}

Product "*" -- "1" Manufacturer : manufacturedBy
Product "*" -- "1" Country : availableIn
Representative "1" -- "1" Country : responsibleFor
Customer "*" -- "*" Country : resellsIn
Representative "1" -- "*" Order : places
Order "*" -- "1" Product : refersTo
Order "*" -- "1" Customer : placedBy

@enduml

